retirement_scan.program_source:
import hashlib
import json
import re
import subprocess
import sys
import time


subject = sys.argv[1]
started = time.monotonic()
commit = subprocess.check_output(
    ["git", "rev-parse", f"{subject}^{{commit}}"], text=True
).strip()
tree = subprocess.check_output(
    ["git", "rev-parse", f"{commit}^{{tree}}"], text=True
).strip()
paths = subprocess.check_output(
    ["git", "ls-tree", "-r", "--name-only", "-z", commit]
).decode().split("\0")
paths = sorted(path for path in paths if path)
file_list = "".join(f"{path}\n" for path in paths).encode()
patterns = {
    "retired_public_flash": r"\b(?:TpFlashResult|FlashError|DiscoverPhases)\b",
    "retired_flash_name": r"\btp_flash\b",
    "retired_lab_or_design": (
        r"(?:cython-held2|cython_held2_experiment|"
        r"generic-relative-permittivity-formulation-design)"
    ),
    "retired_split_sdk": (
        r"(?:epcsaft/include|src/epcsaft/include|"
        r"\bepcsaft-(?:equilibrium|regression)\b|"
        r"\bePC-SAFT/ePC-SAFT-(?:eos|equilibrium|regression)\b)"
    ),
    "retired_regression_switch": (
        r"\b(?:SCHEMA_REGISTRY|ObservationKind|observation_kind|target_index)\b"
    ),
    "retired_literal_phase_route": (
        r"\b(?:x_methane|feed_x_methane|minimum_x_methane|_FLASH_FINGERPRINT)\b"
    ),
    "retired_formulation_selector": (
        r"\b(?:original-born|original_born|permittivity_model)\b"
    ),
    "retired_author_or_campaign_runtime": (
        r"(?:(?:perdomo|khudaida|ascani|cameretti|sadowski|figiel)[_-]"
        r"(?:held2|route|solver|controller|algorithm|workflow|campaign)"
        r"(?:[_-][A-Za-z0-9_-]+)?|"
        r"(?:retained|route|solver|controller|algorithm|workflow|campaign)[_-]"
        r"(?:perdomo|khudaida|ascani|cameretti|sadowski|figiel)"
        r"(?:[_-][A-Za-z0-9_-]+)?|Perdomo HELD2|Perdomo Eq\.)"
    ),
    "retired_campaign_application_selector": (
        r"\b(?:(?:campaign|application)[_-]"
        r"(?:specific|selected|route|solver|controller|dispatch|workflow)|"
        r"(?:route|solver|controller|dispatch|workflow)[_-]"
        r"(?:campaign|application))(?:[_-][A-Za-z0-9_-]+)?\b"
    ),
}
compiled = {name: re.compile(pattern) for name, pattern in patterns.items()}


def classify(path: str) -> tuple[str, str]:
    if (
        path.startswith("engine/tests/fixtures/data/")
        and path.endswith("/provenance/source-origin.toml")
    ):
        return (
            "engine_fixture_source_provenance",
            "Materialized packet fixture provenance preserves its exact source repository locator and never selects runtime or test behavior.",
        )
    if path.startswith(("engine/src/", "engine/cpp/", "engine/tests/")) or path in {
        "engine/CMakeLists.txt",
        "engine/pyproject.toml",
        "engine/tools/check-native-sanitizers.sh",
    }:
        return (
            "live_runtime_or_compact_evidence",
            "No retired match is permitted in live runtime, build, or compact numerical evidence.",
        )
    if path == "governance/GOVERNANCE.md":
        return (
            "accepted_decision_history",
            "Canonical doctrine preserves accepted transition names while declaring the retired surface.",
        )
    if path.startswith("governance/docs/plans/"):
        return (
            "historical_governance_plan",
            "Historical governance plans preserve repository and distribution names as migration provenance.",
        )
    if path.startswith("governance/manifests/"):
        return (
            "migration_manifest",
            "Governance manifests preserve exact source repositories, distributions, hashes, and dispositions.",
        )
    if path.startswith("governance/receipts/"):
        return (
            "immutable_governance_receipt",
            "Existing governance receipts are immutable operation provenance.",
        )
    if path.startswith("validation/"):
        if "/results/" in path or "/reports/" in path:
            kind = "immutable_validation_result"
        elif "/source/" in path or "/data/" in path:
            kind = "validation_source_provenance"
        else:
            kind = "historical_validation_plan_or_guidance"
        return (
            kind,
            "Validation preserves exact installed-route, source, campaign, and historical-plan evidence; it owns no current runtime selector.",
        )
    if path.startswith("data/"):
        return (
            "data_source_provenance",
            "Data preserves exact source repository names, locators, and packet provenance.",
        )
    if path.startswith("lab/provenance/"):
        return (
            "lab_import_provenance",
            "The immutable Lab import manifest preserves pre-deletion paths and hashes.",
        )
    if path.startswith("lab/docs/"):
        return (
            "historical_lab_plan",
            "Historical Lab plans preserve source names and deleted experiment paths as provenance, not executable authority.",
        )
    if path.startswith("engine/evidence/"):
        return (
            "immutable_engine_evidence",
            "Retained Engine evidence preserves historical schemas, distributions, and source identities.",
        )
    if path.startswith("engine/docs/"):
        if "/research/" in path:
            kind = "engine_research_provenance"
        elif "/adr/" in path:
            kind = "accepted_engine_decision_history"
        elif path.endswith("general-parameter-regression.md"):
            kind = "explicitly_superseded_engine_design"
        else:
            kind = "live_retirement_boundary"
        return (
            kind,
            "Engine documentation records accepted or historical provenance or explicitly names an absent retired surface; it is not a runtime selector.",
        )
    return ("unclassified", "No justified exception applies.")


matches = []
binary_paths = []
text_paths = []
for path in paths:
    blob = subprocess.check_output(["git", "show", f"{commit}:{path}"])
    if b"\0" in blob:
        binary_paths.append(path)
        continue
    text_paths.append(path)
    decoded = blob.decode("utf-8", errors="replace")
    lines = decoded.splitlines()
    for pattern_name, regex in compiled.items():
        for occurrence in regex.finditer(decoded):
            line = decoded.count("\n", 0, occurrence.start()) + 1
            line_start = decoded.rfind("\n", 0, occurrence.start()) + 1
            column = occurrence.start() - line_start + 1
            classification, justification = classify(path)
            matches.append(
                {
                    "pattern": pattern_name,
                    "path": path,
                    "line": line,
                    "column": column,
                    "value": occurrence.group(0),
                    "classification": classification,
                    "justification": justification,
                    "excerpt": lines[line - 1].strip()[:320]
                    if line <= len(lines)
                    else "",
                }
            )

blocked = [
    match
    for match in matches
    if match["classification"] in {"live_runtime_or_compact_evidence", "unclassified"}
]
counts_by_pattern = {
    name: sum(match["pattern"] == name for match in matches) for name in patterns
}
counts_by_classification: dict[str, int] = {}
for match in matches:
    key = match["classification"]
    counts_by_classification[key] = counts_by_classification.get(key, 0) + 1

program_sha256 = hashlib.sha256(open(__file__, "rb").read()).hexdigest()
result = {
    "schema_version": 1,
    "subject": {"commit": commit, "tree": tree},
    "invocation": {
        "argv": ["python3", "/tmp/cap11_retirement_scan.py", subject],
        "program_sha256": program_sha256,
    },
    "scope": {
        "included": "all files tracked by the exact subject commit",
        "excluded_paths": [],
        "content_exclusion": "binary blobs containing NUL are listed but not decoded for regex matching",
        "case_semantics": "case-sensitive Python regular expressions",
        "patterns": patterns,
    },
    "file_set": {
        "tracked_file_count": len(paths),
        "text_file_count": len(text_paths),
        "binary_file_count": len(binary_paths),
        "binary_paths": binary_paths,
        "sorted_file_list_sha256": hashlib.sha256(file_list).hexdigest(),
    },
    "matches": matches,
    "terminal_counts": {
        "matches": len(matches),
        "justified_exceptions": len(matches) - len(blocked),
        "blocking_matches": len(blocked),
        "by_pattern": counts_by_pattern,
        "by_classification": dict(sorted(counts_by_classification.items())),
    },
    "result": "pass" if not blocked else "fail",
    "runtime_seconds": round(time.monotonic() - started, 6),
}
print(json.dumps(result, indent=2, sort_keys=True))
sys.exit(1 if blocked else 0)
